class LibraryMember {String id;int limit,books;LibraryMember(String i,int l){if(i==null||i.trim().length()<4)throw new IllegalArgumentException();id=i;limit=l;}void borrowBook(){if(books<limit)books++;}int getBooksBorrowed(){return books;}} class StudentMember extends LibraryMember{String course;StudentMember(String i,int l,String c){super(i,l);course=c;}} public class LibraryEnrollment {static String enrollBatch(String[]x,int l){int ok=0;for(String s:x)try{new LibraryMember(s,l);ok++;}catch(IllegalArgumentException e){}return "Enrolled: "+ok+" | Rejected: "+(x.length-ok);}public static void main(String[]a){System.out.println(enrollBatch(new String[]{"STU1","LB1"},3));}}
